const pj = require('../../package.json');
const fs = require('fs');
const path = require('path');
const { getParameters } = require('../environment');
require('bytenode');

let { report_folder } = getParameters();
let reportFolder = report_folder || 'report';

const allurePDF = require('../../build/allure-pdf/allure-pdf.loader.js');
const versionNumber = pj.version;

const allureConfigPath = path.join(process.cwd(), '/allure-config');

if (!fs.existsSync(path.join(allureConfigPath, '/allure-parameter'))) {
    fs.copyFileSync(
        path.join(allureConfigPath, '/allure-parameter_template'),
        path.join(allureConfigPath, '/allure-parameter'),
    );
}

if (!fs.existsSync(path.join(allureConfigPath, '/allure-configuration.json'))) {
    fs.copyFileSync(
        path.join(allureConfigPath, '/allure-configuration_template.json'),
        path.join(allureConfigPath, '/allure-configuration.json'),
    );
}

let allurePDFName = '',
    allurePDFPath = '';

const regex = new RegExp(/\\/);

if (process.argv.length > 2) {
    if (process.argv.length === 4) {
        allurePDFName = process.argv[2];
        allurePDFPath = process.argv[3];
    } else {
        if (process.argv.includes('--n') || process.argv.includes('--pdfname')) {
            allurePDFName =
                process.argv[
                    process.argv.includes('--n')
                        ? process.argv.indexOf('--n') + 1
                        : process.argv.indexOf('--pdfname') + 1
                ];
        }
        if (process.argv.includes('--p') || process.argv.includes('--pdfpath')) {
            allurePDFPath = process.argv[
                process.argv.includes('--p') ? process.argv.indexOf('--p') + 1 : process.argv.indexOf('--pdfpath') + 1
            ].replace(/"/g, '');
            if (regex.test(allurePDFPath) === true) {
                allurePDFPath = allurePDFPath.split(/\\/g);
                allurePDFPath = path.join(...allurePDFPath);
            }
        }
        if (process.argv.includes('--r') || process.argv.includes('--reportpath')) {
            reportFolder = process.argv[
                process.argv.includes('--r')
                    ? process.argv.indexOf('--r') + 1
                    : process.argv.indexOf('--reportpath') + 1
            ].replace(/"/g, '');
            if (regex.test(reportFolder) === true) {
                reportFolder = reportFolder.split(/\\/g);
                reportFolder = path.join(...reportFolder);
            }
        }
    }
} else {
    let pdfParameters = fs.readFileSync(path.join(allureConfigPath, '/allure-parameter'), { encoding: 'utf-8' });
    pdfParameters = pdfParameters.toString().split('\n');

    for (const parameter of pdfParameters) {
        if (parameter.split('=')[0] === 'allurePdfName') {
            allurePDFName = parameter.split('=')[1].trim();
        } else if (parameter.split('=')[0] === 'allurePdfPath') {
            allurePDFPath = parameter.split('=')[1].trim();
        } else {
            console.log(`Unrecognised parameter ${parameter.split('=')[0]}`);
        }
    }
}

if (!path.isAbsolute(reportFolder)) {
    reportFolder = path.resolve(reportFolder);
}

if (!fs.existsSync(`${reportFolder}`)) {
    console.error(`Error: Invalid Report folder path: ${reportFolder}.`);
    process.exit(1);
}

const allureReportFiles = ['data', 'widgets', 'index.html'];
const folderContents = fs.readdirSync(reportFolder);
if (!reportFolder.endsWith('allure-report') && !allureReportFiles.every(val => folderContents.includes(val))) {
    reportFolder = path.join(reportFolder, 'allure-report');
}

if (!fs.existsSync(`${reportFolder}`)) {
    console.error(`Error: Allure-report folder does not exist in ${reportFolder}.`);
    process.exit(1);
}

if (!path.isAbsolute(allurePDFPath)) {
    allurePDFPath = path.resolve(allurePDFPath);
}

console.log(`Create PDf from report in ${reportFolder} and output to ${allurePDFPath}`);

allurePDF.printAllurePDF(allurePDFName, allurePDFPath, versionNumber, reportFolder);
